Q: Naming methods for a generic type in Rust for backwards compatibility A: <p>Does this break compatibility?</p>
<pre class="lang-rust prettyprint-override"><code>struct BitVecGeneric&lt;B&gt; {
    store: Vec&lt;B&gt;,
}

impl&lt;B&gt; BitVecGeneric&lt;B&gt; {
    fn new() -&gt; Self {
        Self { store: Vec::new() }
    }
}

type BitVec = BitVecGeneric&lt;u32&gt;;

pub fn main() {
    let v = BitVec::new();
    println!(&quot;Hello, world!&quot;);
}

</code></pre>

Q: what pattern allows more freedom in rust when dealing with structs that have intertwined calls? A: <p>This is just not &quot;✨the rust way✨&quot; of designing struct. Try to uncouple the two data type.</p>
<p>You can always avoid mutual reference and just pass reference when needed.</p>
<pre class="lang-rust prettyprint-override"><code>struct Struct1 {}
struct Struct2 {}

impl Struct1 {
    pub fn some_method(&amp;self, struct2: &amp;Struct2) {
        println!(&quot;some_method from struct1&quot;);
        struct2.method_b();
    }
}

impl Struct2 {
    fn method_a(&amp;self, struct1: &amp;Struct1) {
        println!(&quot;method_a from struct2&quot;);
        struct1.some_method(&amp;self);
    }

    fn method_b(&amp;self) {
        println!(&quot;method_b from struct2&quot;);
    }
}

pub fn main() {
    println!(&quot;Running example1&quot;);
    let struct1 = Struct1 {};
    let struct2 = Struct2 {};

    struct2.method_a(&amp;struct1);

    println!(&quot;if you really want to bundle them togehter&quot;);
    let struct3 = Struct3 { struct1, struct2 };
    struct3.method();
}

struct Struct3 {
    struct1: Struct1,
    struct2: Struct2,
}

impl Struct3 {
    fn method(&amp;self) {
        self.struct2.method_a(&amp;self.struct1);
    }
}
</code></pre>
<pre><code>Running example1
method_a from struct2
some_method from struct1
method_b from struct2
if you really want to bundle them togehter
method_a from struct2
some_method from struct1
method_b from struct2
</code></pre>
<h3>You can even do mut ref with minimal change</h3>
<pre class="lang-rust prettyprint-override"><code>struct Struct1 {}
struct Struct2 {}

impl Struct1 {
    pub fn some_method(&amp;mut self, struct2: &amp;mut Struct2) {
        println!(&quot;some_method from struct1&quot;);
        struct2.method_b();
    }
}

impl Struct2 {
    fn method_a(&amp;mut self, struct1: &amp;mut Struct1) {
        println!(&quot;method_a from struct2&quot;);
        struct1.some_method(self);
    }

    fn method_b(&amp;mut self) {
        println!(&quot;method_b from struct2&quot;);
    }
}

pub fn main() {
    println!(&quot;Running example1&quot;);
    let mut struct1 = Struct1 {};
    let mut struct2 = Struct2 {};

    struct2.method_a(&amp;mut struct1);

    println!(&quot;if you really want to bundle them togehter&quot;);
    let mut struct3 = Struct3 { struct1, struct2 };
    struct3.method();
}

struct Struct3 {
    struct1: Struct1,
    struct2: Struct2,
}

impl Struct3 {
    fn method(&amp;mut self) {
        self.struct2.method_a(&amp;mut self.struct1);
    }
}

</code></pre>
